#include <queue>
priority_queue<int> maxPQ;                       // biggest first
maxPQ.push(5); maxPQ.push(9); maxPQ.push(1);
cout << maxPQ.top();                              // 9
maxPQ.pop();                                      // removes 9

priority_queue<int, vector<int>, greater<int>> minPQ;   // smallest first
minPQ.push(5); minPQ.push(9); minPQ.push(1);
cout << minPQ.top();                              // 1
